interface IBus
{
    Task PublishAsync(string key, CancellationToken ct);
    Task PublishAsync(string key) =>
        PublishAsync(key, CancellationToken.None);
}

sealed class RabbitBus : IBus
{
    Task IBus.PublishAsync(string key, CancellationToken ct)
    {
        // publish to RabbitMQ
        return Task.CompletedTask;
    }
}

IBus bus = new RabbitBus();
await bus.PublishAsync("grading.completed");

interface IAttemptHandler
{
    Task HandleAsync(string messageId, CancellationToken ct);
}

interface IHealthCheck
{
    bool IsHealthy();
}

sealed class GradingWorker(IAttemptStore store) : IAttemptHandler, IHealthCheck
{
    public Task HandleAsync(string messageId, CancellationToken ct) =>
        store.ProcessAsync(messageId, ct);

    public bool IsHealthy() => store.CanConnect();
}

interface ICacheKey
{
    string Value { get; }
}

readonly struct RedisKey(string value) : ICacheKey
{
    public string Value { get; } = value;
}

ICacheKey key = new RedisKey("tenant:acme"); // boxes the struct
RedisKey direct = new RedisKey("tenant:acme"); // no boxing

interface IInbound { void Handle(string msg); }
interface IOutbound { void Handle(string msg); }

sealed class Bridge : IInbound, IOutbound
{
    void IInbound.Handle(string msg) => Console.WriteLine($"in: {msg}");
    void IOutbound.Handle(string msg) => Console.WriteLine($"out: {msg}");
}

var b = new Bridge();
// b.Handle("x"); // compile error — hidden from class surface
((IInbound)b).Handle("x");
